SELECT ,
       (
           SELECT COALESCE(SUM(pay11_item_amt), 0)
             FROM pay11_month_item
                  INNER JOIN pay10_month ON pay11_month_id = pay10_month_id
            WHERE pay10_person_id = pay31_person_id
              AND pay10_date BETWEEN #{startDate}::date AND #{closeDate}::date
              AND pay11_item_cd IN ('220','230')
       )                                                                         AS insure_year_pay
  FROM pay31_insure_apply
       INNER JOIN emp01_person ON emp01_person_id = pay31_person_id
 WHERE pay31_company_id = #{companyId}
   AND pay31_insure_cd LIKE #{insureCode}


   AND pay31_insure_apply_cd IN ('2','3')


   AND pay31_insure_apply_cd = #{insureApplyGubun}




   AND TO_CHAR(pay31_apply_date,'YYYY') = #{year}


   AND f_trunc(pay31_apply_date) BETWEEN #{startDate} AND #{closeDate}



   AND pay31_person_id = #{personId}

 ORDER BY emp01_emp_no

SELECT ,
       NULL::numeric                                                             AS insure_year_pay
  FROM pay31_insure_apply
       INNER JOIN emp01_person ON emp01_person_id = pay31_person_id
 WHERE pay31_insure_apply_id = #{insureApplyId}
   AND pay31_company_id = #{companyId}

