SELECT emp35_repr_yn
  FROM emp35_deduct
 WHERE emp35_start_date = (
           SELECT MAX(emp35_start_date)
             FROM emp35_deduct
            WHERE emp35_company_id = #{companyId}
              AND emp35_start_date <= #{startDate}
              AND emp35_person_id = #{personId})
   AND emp35_company_id = #{companyId}
   AND emp35_person_id = #{personId}
 LIMIT 1

SELECT emp01_hire_date
  FROM emp01_person
 WHERE emp01_person_id = #{personId}
   AND emp01_company_id = #{companyId}

SELECT COUNT(*)
  FROM emp01_person
 WHERE emp01_person_id = #{personId}
   AND emp01_company_id = #{companyId}

SELECT emp01_person.emp01_person_id
  FROM emp01_person
       INNER JOIN emp02_others ON emp01_person_id = emp02_person_id
 WHERE emp01_company_id = #{companyId}
   AND emp01_kor_nm = #{personName}
   AND LEFT(to_decrypts(emp02_ctz_no), 6) = LEFT(#{personCtzNo}, 6)

SELECT emp01_person_id
  FROM emp01_person
 WHERE emp01_company_id = #{companyId}
   AND emp01_emp_no = #{empNo}
